SELECT  FROM students

    AND active = TRUE
    AND disability_type = #{disabilityType}
    AND support_level = #{supportLevel}
    AND class_group = #{classGroup}

        AND (full_name LIKE CONCAT('%', #{keyword}, '%')
             OR student_code LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY full_name

mapper.update:
UPDATE students SET student_code = #{studentCode}, full_name = #{fullName},
    date_of_birth = #{dateOfBirth}, gender = #{gender}, disability_type = #{disabilityType},
    support_level = #{supportLevel}, enrollment_date = #{enrollmentDate},
    class_group = #{classGroup}, notes = #{notes}
WHERE id = #{id}
